<?php
namespace qqworld_collector\module; use qqworld_collector\lib; class proxy extends lib { var $options; var $module = 'proxy'; var $settings_name = 'qqworld-collector-proxy'; public function __construct() { if ( !apply_filters( 'qqworld-collector-activated', false ) ) return; if ( apply_filters( 'qqworld-collector-activated-license', false ) && !apply_filters( 'qqworld-collector-activated-module-' . $this->module, false ) ) return; add_action( 'admin_menu', array($this, 'admin_menu') ); add_action( 'admin_init', array($this, 'register_settings') ); add_action( 'admin_enqueue_scripts', array($this, 'admin_enqueue_scripts') ); add_filter( 'qqworld-collector-script-translation-array', array($this, 'add_translation_array') ); add_action( 'wp_ajax_qqworld-collector-check-proxy-address', array($this, 'check_proxy_address') ); add_action( 'wp_ajax_nopriv_qqworld-collector-check-proxy-address', array($this, 'check_proxy_address') ); add_action( 'wp_ajax_qqworld-collector-view-dynamic-proxy-cache', array($this, 'view_dynamic_proxy_cache') ); add_action( 'wp_ajax_nopriv_qqworld-collector-view-dynamic-proxy-cache', array($this, 'view_dynamic_proxy_cache') ); add_action( 'wp_ajax_qqworld-collector-delete-dynamic-proxy-cache', array($this, 'delete_dynamic_proxy_cache') ); add_action( 'wp_ajax_nopriv_qqworld-collector-delete-dynamic-proxy-cache', array($this, 'delete_dynamic_proxy_cache') ); add_action( 'http_api_curl', array($this, 'http_api_curl') ); } public function admin_menu() { $parent_slug = 'qqworld-collector'; $page_title = __('Proxy', $this->text_domain); $menu_title = $page_title; $capability = !$this->options->qc_authorization_all_roles_can_modify_settings ? 'manage_options' : $this->options->qc_authorization_who_can_use; $menu_slug = 'qqworld-collector-proxy'; $function = array($this, 'proxy'); $settings_page = add_submenu_page($parent_slug, $page_title, $menu_title, $capability, $menu_slug, $function); add_action( "load-{$settings_page}", array($this, 'help_tab') ); } public function register_settings() { register_setting($this->settings_name, $this->settings_name, array($this, 'clear_cache') ); } public function clear_cache($value) { global $blog_id; if ($value && is_array($value)) { $GLOBALS['QC']->cache->delete_cache('qqworld-collector-proxy-' . $value['mode'] . '-' . $blog_id); } return $value; } public function proxy() { global $blog_id; require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'proxy.php'; } public function admin_enqueue_scripts() { $screen = get_current_screen(); if (strstr($screen->id, $this->settings_name)) { wp_enqueue_script('qqworld-collector-proxy-admin'); wp_enqueue_style('animate'); wp_enqueue_script('noty'); wp_enqueue_style('noty'); } } public function add_translation_array($translation_array) { $translation_array['proxy_activated'] = apply_filters( 'qqworld-collector-activated-module-proxy', false ); $translation_array['text']['proxy_address_checked'] = __('All proxy addresses have been detected.', $this->text_domain); return $translation_array; } public function ping($ip){ $ip = preg_replace('/@.*/', '', $ip); $ip_port = explode(':', trim($ip)); $ip = gethostbyname($ip_port[0]); if ( filter_var( $ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6) ) { $socket = socket_create(AF_INET6, SOCK_STREAM, SOL_TCP); } elseif ( filter_var( $ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) ) { $socket = socket_create(AF_INET, SOCK_STREAM, SOL_TCP); } else { return FALSE; } if( !isset($ip_port[1]) ) { $ip_port[1] = '80'; } $ok = socket_connect($socket, $ip, $ip_port[1]); socket_close($socket); return $ok; } public function check_proxy_address() { set_time_limit(600); if (!isset($_POST['address'])) exit; $address = explode("\n", $_POST['address']); if (!empty($address)) { foreach ($address as $index => &$addr) { $addr = preg_replace('/\t.*/i', '', $addr); $ok = $this->ping($addr); if (!$ok) { unset($address[$index]); } } } print implode("\n", $address); exit; } public function view_dynamic_proxy_cache() { global $blog_id; $proxy = $GLOBALS['QC']->cache->get_cache('qqworld-collector-proxy-' . $this->options->qc_proxy_mode . '-' . $blog_id); print strip_tags($proxy); exit; } public function delete_dynamic_proxy_cache() { global $blog_id; $GLOBALS['QC']->cache->delete_cache('qqworld-collector-proxy-' . $this->options->qc_proxy_mode . '-' . $blog_id); $results = array( 'success' => 1, 'msg' => __('Successfully deleted dynamic proxy cache.', $this->text_domain) ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function http_api_curl($handle) { if (isset($GLOBALS['PROXY_ENABLED'])) { if ( !$GLOBALS['PROXY_ENABLED'] ) return; if ( !isset($GLOBALS['PROXY_ADDRESS']) || !$GLOBALS['PROXY_ADDRESS'] ) return; } else { if ( !$this->options->qc_proxy_enabled ) return; else $GLOBALS['PROXY_ADDRESS'] = apply_filters( 'qqworld-collector-get-proxy', '' ); } if ($this->options->qc_proxy_mode == 'auto') return; if (isset($GLOBALS['PROXY_ADDRESS']) && $GLOBALS['PROXY_ADDRESS']) { $proxy_address = explode('@', $GLOBALS['PROXY_ADDRESS'], 2); $proxy = explode(':', $proxy_address[0]); curl_setopt($handle, CURLOPT_PROXY, gethostbyname($proxy[0])); curl_setopt($handle, CURLOPT_PROXYPORT, $proxy[1]); if (count($proxy_address) == 2) { curl_setopt($handle, CURLOPT_PROXYUSERPWD, $proxy_address[1]); } if ( !defined('CURLOPT_PROXYTYPE') ) return; switch ($this->options->qc_proxy_type) { case 'CURLPROXY_SOCKS4': $proxy_type = CURLPROXY_SOCKS4; break; case 'CURLPROXY_SOCKS5': $proxy_type = CURLPROXY_SOCKS5; break; case 'CURLPROXY_SOCKS4A': $proxy_type = CURLPROXY_SOCKS4A; break; case 'CURLPROXY_SOCKS5_HOSTNAME': $proxy_type = CURLPROXY_SOCKS5_HOSTNAME; break; case 'CURLPROXY_HTTP': $proxy_type = CURLPROXY_HTTP; break; } curl_setopt($handle, CURLOPT_PROXYTYPE, $proxy_type); } } } ?>